#include <omp.h>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <vector>

double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("sumOfMinimumElements: x and y must have the same size");
    }

    const std::size_t n = x.size();
    if (n == 0) {
        return 0.0;
    }

    if (n > static_cast<std::size_t>(std::numeric_limits<long long>::max())) {
        throw std::length_error("sumOfMinimumElements: input size exceeds OpenMP loop index range");
    }

    const long long n_ll = static_cast<long long>(n);
    double sum = 0.0;

    #pragma omp parallel for default(none) shared(x, y, n_ll) reduction(+:sum)
    for (long long i = 0; i < n_ll; ++i) {
        sum += std::min(x[static_cast<std::size_t>(i)],
                        y[static_cast<std::size_t>(i)]);
    }

    return sum;
}
